  json: {
    richiesta: {
      model: String(cfg.CLAUDE_MODEL || '').trim() || 'claude-opus-5-5',
      max_tokens: 800,
      fallbacks: 'default',
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
      system: SISTEMA,
      messages: [{ role: 'user', content: [{ type: 'text', text: TESTO }] }],
    },
  },
